function githubReleaseParts({ body }) {
  if (
    !body ||
    typeof body !== "object" ||
    Array.isArray(body) ||
    typeof body.action !== "string" ||
    !body.action ||
    !body.repository ||
    !body.release
  )
    throw new Error("Expected a GitHub release event");
  const repository = body.repository.full_name,
    tag = body.release.tag_name,
    notes = body.release.body,
    link = body.release.html_url;
  if (
    typeof repository !== "string" ||
    !repository.trim() ||
    typeof tag !== "string" ||
    !tag.trim() ||
    (notes != null && typeof notes !== "string") ||
    typeof link !== "string"
  )
    throw new Error("The release is missing its repository, tag, notes or URL");
  if (!/^https:\/\/[^\s/?#@<>"'\\]+(?:[/?#][^\s<>"'\\]*)?$/.test(link))
    throw new Error("Expected the release’s real HTTPS URL without credentials");
  const text =
    "New release is available in " +
    repository +
    " !\n" +
    tag +
    " Details:\n" +
    (notes ?? "") +
    "\n\nLink: " +
    link;
  const chunks = [];
  let chunk = "";
  for (const character of text) {
    if (chunk.length + character.length > 3900) {
      chunks.push(chunk);
      chunk = "";
    }
    chunk += character;
  }
  if (chunk) chunks.push(chunk);
  const parts = chunks.map((content, index) =>
    chunks.length > 1 ? "Part " + (index + 1) + "/" + chunks.length + "\n" + content : content,
  );
  if (parts.some((part) => part.length > 4000))
    throw new Error("The release part exceeds the message budget");
  return { parts, action: body.action };
}

const items = $input.all();
if (items.length !== 1) throw new Error("Expected one GitHub release event");
const result = githubReleaseParts({ body: items[0].json.body });
return result.parts.map((text, index) => ({
  json: { text, index: index + 1, action: result.action },
  pairedItem: { item: 0 },
}));

const requests = $("Format the complete release notice").all();
if (!Number.isInteger($runIndex) || $runIndex < 0 || $runIndex >= requests.length)
  throw new Error("Invalid release message index");
const channel = $("Post one release message to Slack").params.channel;
if (
  $json.ok !== true ||
  typeof $json.ts !== "string" ||
  !/^\d+\.\d+$/.test($json.ts) ||
  $json.channel !== channel
)
  throw new Error(
    "Slack did not confirm the release message in the requested channel; posting may already have occurred",
  );
return {
  json: {
    part: requests[$runIndex].json.index,
    action: requests[$runIndex].json.action,
    message: $json,
  },
};
